mapper.select:
SELECT extends.supply_bonus AS supply_bonus, extends.rebate_bonus AS rebate_bonus, extends.user_id AS user_id, extends.user_id AS shop_user_id, extends.nickname AS nike_name, extends.avatar AS avatar_url, extends.first_login_time AS first_login_time, extends.last_deal_time AS last_deal_time, extends.consume_num AS consume_num, extends.consume_totle_money AS consume_totle_money, extends.integral AS integral FROM t_mini_account_extends AS extends WHERE extends.shop_id = #{paramMap.shopId} AND EXISTS ( SELECT memberInfo.id FROM t_member_info AS memberInfo LEFT JOIN t_member_card_info as card ON card.id = memberInfo.member_card_info_id WHERE memberInfo.user_id = extends.user_id AND memberInfo.is_deleted = 0 AND memberInfo.state = 1 AND memberInfo.member_expire_time > SYSDATE()
AND memberInfo.member_register_time >= #{paramMap.becomeMemberStartTime}
AND memberInfo.member_register_time <= #{paramMap.becomeMemberEndTime}
AND memberInfo.member_number = #{paramMap.memberNumber}
AND memberInfo.member_info_id = #{paramMap.memberCardId}
AND card.rank_code = #{paramMap.rankCode}
) AND extends.is_deleted = 0
AND EXISTS ( SELECT tagGroup.id FROM t_mini_account_tag_group AS tagGroup WHERE tagGroup.user_id = extends.user_id AND tagGroup.tag_id = #{paramMap.tagId} AND tagGroup.is_deleted=0 )
AND LOCATE( #{paramMap.nikeName}, extends.nickname )
AND extends.last_deal_time >= #{paramMap.orderSuccessStartTime}
AND extends.last_deal_time <= #{paramMap.orderSuccessEndTime}
ORDER BY user_id DESC
ORDER BY consume_totle_money DESC
ORDER BY consume_totle_money ASC

mapper.update:
update t_member_info t
set t.member_expire_time = #{updateMemberExpireTimeDto.memberExpireTime}
where t.member_number = #{updateMemberExpireTimeDto.memberNumber}

update t_member_info t
set t.member_expire_time = #{updateApiMemberExpireTimeDto.memberExpireTime}
where t.member_number = #{updateApiMemberExpireTimeDto.memberNumber}

update t_member_info
set member_card_info_id = (SELECT id
                           FROM t_member_card_info
                           where shop_id = #{upgradeMemberRankDto.shopId}
                             and rank_code = #{upgradeMemberRankDto.rankCode}
                             and is_deleted = 0
                             and open_type = (
                                   SELECT current_open_type
                                   FROM t_member_card_base_info
                                   where shop_id = #{upgradeMemberRankDto.shopId}
                                   )
        )
where member_number = #{upgradeMemberRankDto.memberNumber}

