                           FROM t_member_card_info
                           where shop_id = #{upgradeApiMemberRankDto.shopId}
                             and rank_code = #{upgradeApiMemberRankDto.rankCode}
                             and is_deleted = 0
                             and open_type = (
                               SELECT current_open_type
                               FROM t_member_card_base_info
                               where shop_id = #{upgradeApiMemberRankDto.shopId}
                           )
        )
where member_number = #{upgradeApiMemberRankDto.memberNumber}

mapper.select:
select count(t.id) from t_member_info t
left join t_member_card_info tm on tm.id = t.member_card_info_id
where t.is_deleted = 0

    AND t.shop_id = #{shopId}


    AND tm.rank_code = #{rankCode}

select
tmi.id,tmi.member_number,tmi.member_register_time,tmi.member_expire_time,
tmc.rank_code,tmc.rank_name,tmc.open_type,tmc.title,tmc.open_value
from
t_member_info as tmi
left join t_member_card_info as tmc on tmc.id = tmi.member_card_info_id

    1=1
    
        and tmc.rank_name like #{paramMap.rankName}
    
    
        and tmc.title like #{paramMap.title}
    
    
        and tmi.user_id = #{paramMap.shopUserId}
    
    
        and tmi.member_number like #{paramMap.memberNumber}
    
    
        and tmi.member_register_time >= #{paramMap.becomeMemberStartTime}
    
    
        and  tmi.member_register_time <= #{paramMap.becomeMemberEndTime}
